<?php declare(strict_types=1); require dirname(__DIR__).'/vendor/autoload.php'; use Paxofi\CorporateWebsite\Http\JsonResponse; $path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/'; $method=$_SERVER['REQUEST_METHOD']??'GET'; $requestId=bin2hex(random_bytes(8)); if($path==='/api/v1/health'&&$method==='GET'){JsonResponse::send(['success'=>true,'data'=>['status'=>'ok','service'=>'paxofi-corporate-website-api'],'meta'=>[],'request_id'=>$requestId]);} if($path==='/api/v1/content'&&$method==='GET'){JsonResponse::send(['success'=>true,'data'=>[],'meta'=>['published'=>true],'request_id'=>$requestId]);} if($path==='/api/v1/careers'&&$method==='GET'){JsonResponse::send(['success'=>true,'data'=>[],'meta'=>['published'=>true],'request_id'=>$requestId]);} if(preg_match('#^/api/v1/forms/([^/]+)/submit$#',$path,$m)&&$method==='POST'){ $input=json_decode(file_get_contents('php://input'),true); if(!is_array($input)){$input=$_POST;} if(empty($input['name'])||empty($input['email'])||empty($input['message'])) JsonResponse::send(['success'=>false,'error'=>['code'=>'VALIDATION_ERROR','message'=>'Name, email and message are required.'],'request_id'=>$requestId],422); JsonResponse::send(['success'=>true,'data'=>['accepted'=>true,'form_key'=>$m[1]],'meta'=>[],'request_id'=>$requestId],202);} JsonResponse::send(['success'=>false,'error'=>['code'=>'NOT_FOUND','message'=>'Resource not found.'],'request_id'=>$requestId],404);